    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==v and not seen[i][j]:
                st=[(i,j)]; c=[]
                while st:
                    x,y=st.pop()
                    if seen[x][y]: continue
                    seen[x][y]=True; c.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<h and 0<=b<w and not seen[a][b] and g[a][b]==v: st.append((a,b))
                out.append(c)
    return out
